import { router, json, error, db, ai, storage } from '@appdeploy/sdk';import { notifySubscribers, realtimeSubscriptionRoutes } from './realtime-subscribers';
import { randomBytes, scryptSync, timingSafeEqual } from 'node:crypto';

type Role='customer'|'order'|'cashier'|'barista'|'staff'|'admin';
type UserRec={username:string;name:string;email:string;phone:string;role:Role;salt:string;hash:string;points:number;createdAt:string;isSuperAdmin?:boolean};
type SessionRec={userId:string;token:string;role:Role;username:string;expiresAt:number};
type BankRec={bankName:string;accountNumber:string;accountName:string;bankCode:string;isDefault:boolean;createdAt:string};type ShopSettingsRec={address:string;phone:string;email:string;hours:string;openTime?:string;closeTime?:string;open24h?:boolean;temporarilyClosed?:boolean;closedMessage?:string;facebook:string;zalo:string;mapUrl:string;updatedAt:string};type VoucherRec={code:string;title:string;description:string;cta?:string;discountType:'percent'|'fixed';discountValue:number;minOrder:number;maxDiscount:number;usageLimit:number;used:number;startAt:string;endAt:string;active:boolean;showBanner:boolean;imagePath:string;createdAt:string;updatedAt:string};
const norm=(v:string)=>String(v||'').trim().toLowerCase();
const phoneNorm=(v:string)=>String(v||'').replace(/\D/g,'');
const hash=(password:string,salt:string)=>scryptSync(password,salt,64).toString('hex');
const safe=(a:string,b:string)=>{try{return timingSafeEqual(Buffer.from(a,'hex'),Buffer.from(b,'hex'))}catch{return false}};
async function findUser(login:string){const key=norm(login);const phone=phoneNorm(login);const {items}=await db.list<UserRec>('users',{limit:100});return items.find(x=>x.username===key||(phone&&phoneNorm(x.phone)===phone))||null}
async function findPhone(phone:string){const p=phoneNorm(phone);if(!p)return null;const {items}=await db.list<UserRec>('users',{limit:100});return items.find(x=>phoneNorm(x.phone)===p)||null}
async function adminExists(){const {items}=await db.list<UserRec>('users',{limit:100});return items.some(x=>x.role==='admin')}async function ensureSuperAdmin(){const {items}=await db.list<UserRec>('users',{limit:100});const marked=items.find(x=>x.isSuperAdmin===true);if(marked)return marked;const first=items.filter(x=>x.role==='admin').sort((a,b)=>String(a.createdAt||'').localeCompare(String(b.createdAt||'')))[0];if(!first)return null;const [ok]=await db.update('users',[{id:first.id,record:{...first,isSuperAdmin:true}}]);return ok?{...first,isSuperAdmin:true}:first}
async function session(token:string){if(!token)return null;const {items}=await db.list<SessionRec>('sessions',{filter:{token},limit:50});const s=items.find(x=>x.token===token);return s&&s.expiresAt>Date.now()?s:null}
async function cashierSession(token:string){const s=await session(token);return s&&(['order','cashier','staff','admin'] as Role[]).includes(s.role)?s:null} async function baristaSession(token:string){const s=await session(token);return s&&(['barista','admin'] as Role[]).includes(s.role)?s:null}
async function consumeRecipes(items:any[]){const {items:recipes}=await db.list<Record<string,any>>('recipes',{limit:300});if(!recipes.length)return;const {items:bases}=await db.list<Record<string,any>>('base_recipes',{limit:100});const need=new Map<string,number>();for(const item of items){for(const r of recipes.filter(x=>String(x.productId)===String(item.id)&&x.baseRecipeId&&(!x.size||String(x.size).toUpperCase()===String(item.size||'M').toUpperCase()))){const amount=Math.max(0,Number(r.amount||0))*Math.max(0,Number(item.qty||0));if(amount>0)need.set(String(r.baseRecipeId),(need.get(String(r.baseRecipeId))||0)+amount)}}for(const [baseRecipeId,amount] of need){const base=bases.find(x=>String(x.id)===baseRecipeId);if(base)await db.update('base_recipes',[{id:baseRecipeId,record:{...base,outputStock:Math.max(0,Number(base.outputStock||0)-amount),updatedAt:new Date().toISOString()}}])}}async function restoreRecipes(items:any[]){const {items:recipes}=await db.list<Record<string,any>>('recipes',{limit:300});if(!recipes.length)return;const {items:bases}=await db.list<Record<string,any>>('base_recipes',{limit:100});const restore=new Map<string,number>();for(const item of items){for(const r of recipes.filter(x=>String(x.productId)===String(item.id)&&x.baseRecipeId&&(!x.size||String(x.size).toUpperCase()===String(item.size||'M').toUpperCase()))){const amount=Math.max(0,Number(r.amount||0))*Math.max(0,Number(item.qty||0));if(amount>0)restore.set(String(r.baseRecipeId),(restore.get(String(r.baseRecipeId))||0)+amount)}}for(const [baseRecipeId,amount] of restore){const base=bases.find(x=>String(x.id)===baseRecipeId);if(base)await db.update('base_recipes',[{id:baseRecipeId,record:{...base,outputStock:Number(base.outputStock||0)+amount,updatedAt:new Date().toISOString()}}])}}
const voucherTimeMs=(value:string)=>{const s=String(value||'').trim();if(!s)return NaN;const hasZone=/Z$|[+-]\d{2}:?\d{2}$/.test(s);return new Date(hasZone?s:s+'+07:00').getTime()};async function ensureVouchers(){const {items}=await db.list<VoucherRec>('vouchers',{limit:100});if(items.length)return items;const now=new Date().toISOString();await db.add('vouchers',[{code:'GREEN20',title:'Giảm 20% cho đơn từ 99K',description:'Ưu đãi VoiTea hôm nay - giảm tối đa 30.000đ',discountType:'percent',discountValue:20,minOrder:99000,maxDiscount:30000,usageLimit:0,used:0,startAt:'2026-01-01T00:00:00.000Z',endAt:'2027-12-31T23:59:59.000Z',active:true,showBanner:true,imagePath:'',createdAt:now,updatedAt:now},{code:'VOITEA10',title:'VoiTea giảm 10%',description:'Giảm 10% cho đơn từ 50.000đ, tối đa 15.000đ',discountType:'percent',discountValue:10,minOrder:50000,maxDiscount:15000,usageLimit:0,used:0,startAt:'2026-01-01T00:00:00.000Z',endAt:'2027-12-31T23:59:59.000Z',active:true,showBanner:true,imagePath:'',createdAt:now,updatedAt:now}]);return (await db.list<VoucherRec>('vouchers',{limit:100})).items}function voucherLive(v:VoucherRec,now=Date.now()){return v.active!==false&&(!v.startAt||voucherTimeMs(v.startAt)<=now)&&(!v.endAt||voucherTimeMs(v.endAt)>=now)&&(Number(v.usageLimit||0)<=0||Number(v.used||0)<Number(v.usageLimit||0))}async function voucher(code:string,subtotal:number){const c=String(code||'').trim().toUpperCase();if(!c)return {valid:false,code:'',discount:0,message:'',voucherId:''};const rows=await ensureVouchers();const v=rows.find(x=>String(x.code).toUpperCase()===c);if(!v)return {valid:false,code:c,discount:0,message:'Mã voucher không hợp lệ',voucherId:''};if(!voucherLive(v))return {valid:false,code:c,discount:0,message:'Voucher chưa đến thời gian sử dụng, đã hết hạn hoặc hết lượt',voucherId:v.id};if(subtotal<Number(v.minOrder||0))return {valid:false,code:c,discount:0,message:`Đơn tối thiểu ${Number(v.minOrder||0).toLocaleString('vi-VN')}đ`,voucherId:v.id};let discount=v.discountType==='fixed'?Number(v.discountValue||0):Math.round(subtotal*Number(v.discountValue||0)/100);if(Number(v.maxDiscount||0)>0)discount=Math.min(discount,Number(v.maxDiscount));discount=Math.min(discount,subtotal);return {valid:true,code:c,discount,message:v.description||v.title||'Voucher hợp lệ',voucherId:v.id}}
